      SUBROUTINE ENRIMCC     CALCULATES NEW TRANSFER MATRIX FOR MISALIGNMENT TABLEC     ABOUT DISPLACED TRAJECTORYCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RA.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TA.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UA.CIN'CC---------------------------------------------------------------CC     TRANSFER OF MATRICES TO WORK AREASC      DO 5 JK = 1, 36    5 RAL(JK) = RL(JK)      IF (NORD1 .GE. 2) THEN        DO 10 JKL = 1, 105   10   TAL(JKL) = TL(JKL)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 12 JKLM = 1, 280   12   UAL(JKLM) = UL(JKLM)      ENDIFCC     CONTRIBUTION OF HIGHER-ORDER MATRICES TO OFF-AXIS LOWER ORDERC  100 IF (NORD1 .GE. 2) CALL ENRIC2      IF (NORD1 .GE. 3) CALL ENRIC3CC     TRANSFER OF MATRICES FROM WORK AREASC      DO 105 JK = 1, 36  105 RL(JK) = RAL(JK)      IF (NORD2 .GE. 2) THEN        DO 110 JKL = 1, 105  110   TL(JKL) = TAL(JKL)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 112 JKLM = 1, 280  112   UL(JKLM) = UAL(JKLM)      ENDIFC  200 RETURN      END